#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    int sizes[] = {1<<20, 5<<20, 40<<20};
    unsigned char key[32] = {0};
    unsigned char nonce[12] = {0};
    unsigned char aad[32] = {0};
    for (int s = 0; s < 3; s++) {
        int len = sizes[s];
        unsigned char *pt = malloc(len);
        unsigned char *ct = malloc(len + 16);
        memset(pt, 1, len);
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        // warmup
        int outl = 0, fin = 0;
        EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outl, pt, 1024);
        EVP_EncryptFinal_ex(ctx, ct + outl, &fin);
        unsigned char tag[16];
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);

        double t0 = now();
        int iters = (len >= 40<<20) ? 3 : 8;
        int total_out = 0;
        for (int i = 0; i < iters; i++) {
            EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, NULL, NULL);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
            EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
            EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
            EVP_EncryptUpdate(ctx, ct, &outl, pt, len);
            total_out = outl;
            EVP_EncryptFinal_ex(ctx, ct + outl, &fin);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
        }
        double t1 = now();
        printf("%d MB: %.2f ms  %.1f MB/s  out=%d\n", len>>20, (t1-t0)/iters*1000, (double)len*iters/(t1-t0)/1e6, total_out);
        // also one-shot init reuse
        double t2 = now();
        for (int i = 0; i < iters; i++) {
            EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
            EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
            EVP_EncryptUpdate(ctx, ct, &outl, pt, len);
            EVP_EncryptFinal_ex(ctx, ct + outl, &fin);
            EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
        }
        double t3 = now();
        printf("  reuse: %.2f ms  %.1f MB/s\n", (t3-t2)/iters*1000, (double)len*iters/(t3-t2)/1e6);
        EVP_CIPHER_CTX_free(ctx);
        free(pt); free(ct);
    }
    return 0;
}
EOF
