{"command":"mkdir -p ./gobench && cat > ./gobench/main.go << 'EOF'
package main

import (
	"crypto/rand"
	"fmt"
	"time"
	"golang.org/x/crypto/chacha20poly1305"
)

func main() {
	key := make([]byte, 32)
	nonce := make([]byte, 12)
	rand.Read(key)
	rand.Read(nonce)
	aead, err := chacha20poly1305.New(key)
	if err != nil { panic(err) }
	aad := make([]byte, 32)
	for _, mb := range []int{1, 5, 40} {
		pt := make([]byte, mb<<20)
		rand.Read(pt)
		// warmup
		_ = aead.Seal(nil, nonce, pt[:1024], aad)
		iters := 5
		if mb >= 40 { iters = 3 }
		t0 := time.Now()
		var ct []byte
		for i := 0; i < iters; i++ {
			ct = aead.Seal(ct[:0], nonce, pt, aad)
		}
		dt := time.Since(t0)
		fmt.Printf("%d MB: %.2f ms  %.1f MB/s  ctlen=%d\n", mb, float64(dt.Microseconds())/float64(iters)/1000.0, float64(len(pt)*iters)/dt.Seconds()/1e6, len(ct))
	}
}
EOF
