#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t len = 40<<20;
    uint8_t *a = aligned_alloc(64, len);
    uint8_t *b = aligned_alloc(64, len);
    memset(a, 1, len);
    // warmup
    memcpy(b, a, len);
    int iters = 20;
    double t0 = now();
    for (int i = 0; i < iters; i++) memcpy(b, a, len);
    double t1 = now();
    printf("memcpy 40MB: %.3f ms  %.1f MB/s (copy)  traffic %.1f GB/s\n",
        (t1-t0)/iters*1000, (double)len*iters/(t1-t0)/1e6, 2.0*len*iters/(t1-t0)/1e9);

    // read+write with xor (simulate cipher traffic, non-streaming store?)
    t0 = now();
    for (int i = 0; i < iters; i++) {
        for (size_t j = 0; j < len; j += 64) {
            __builtin_prefetch(a+j+256, 0, 0);
            uint64_t *s = (uint64_t*)(a+j);
            uint64_t *d = (uint64_t*)(b+j);
            d[0]=s[0]^0x1234; d[1]=s[1]^0x1234; d[2]=s[2]^0x1234; d[3]=s[3]^0x1234;
            d[4]=s[4]^0x1234; d[5]=s[5]^0x1234; d[6]=s[6]^0x1234; d[7]=s[7]^0x1234;
        }
    }
    double t2 = now();
    printf("xor64 40MB: %.3f ms  %.1f MB/s  traffic %.1f GB/s\n",
        (t2-t0)/iters*1000, (double)len*iters/(t2-t0)/1e6, 2.0*len*iters/(t2-t0)/1e9);

    // nt stores
    t0 = now();
    for (int i = 0; i < iters; i++) {
        for (size_t j = 0; j < len; j += 64) {
            __m128i v0 = _mm_loadu_si128((__m128i*)(a+j));
            __m128i v1 = _mm_loadu_si128((__m128i*)(a+j+16));
            __m128i v2 = _mm_loadu_si128((__m128i*)(a+j+32));
            __m128i v3 = _mm_loadu_si128((__m128i*)(a+j+48));
            __m128i k = _mm_set1_epi32(0x1234);
            _mm_stream_si128((__m128i*)(b+j), _mm_xor_si128(v0, k));
            _mm_stream_si128((__m128i*)(b+j+16), _mm_xor_si128(v1, k));
            _mm_stream_si128((__m128i*)(b+j+32), _mm_xor_si128(v2, k));
            _mm_stream_si128((__m128i*)(b+j+48), _mm_xor_si128(v3, k));
        }
        _mm_sfence();
    }
    double t3 = now();
    printf("nt xor 40MB: %.3f ms  %.1f MB/s  traffic %.1f GB/s\n",
        (t3-t0)/iters*1000, (double)len*iters/(t3-t0)/1e6, 2.0*len*iters/(t3-t0)/1e9);
    printf("sink %u\n", b[0]);
    return 0;
}
EOF
