#include <immintrin.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t len = 40u<<20;
    uint8_t *a = aligned_alloc(64, len);
    uint8_t *b = aligned_alloc(64, len);
    memset(a, 1, len);
    memset(b, 2, len);
    int iters = 10;

    // AVX2 streaming copy (read + nt write)
    double t0 = now();
    for (int i = 0; i < iters; i++) {
        for (size_t j = 0; j < len; j += 128) {
            __m256i v0 = _mm256_loadu_si256((__m256i*)(a+j));
            __m256i v1 = _mm256_loadu_si256((__m256i*)(a+j+32));
            __m256i v2 = _mm256_loadu_si256((__m256i*)(a+j+64));
            __m256i v3 = _mm256_loadu_si256((__m256i*)(a+j+96));
            _mm256_stream_si256((__m256i*)(b+j), v0);
            _mm256_stream_si256((__m256i*)(b+j+32), v1);
            _mm256_stream_si256((__m256i*)(b+j+64), v2);
            _mm256_stream_si256((__m256i*)(b+j+96), v3);
        }
        _mm_sfence();
    }
    double t1 = now();
    printf("avx2 stream copy: %.3f ms  %.1f MB/s data  %.1f GB/s traffic\n",
        (t1-t0)/iters*1000, (double)len*iters/(t1-t0)/1e6, 2.0*len*iters/(t1-t0)/1e9);

    // regular avx2 copy
    t0 = now();
    for (int i = 0; i < iters; i++) {
        for (size_t j = 0; j < len; j += 128) {
            __m256i v0 = _mm256_loadu_si256((__m256i*)(a+j));
            __m256i v1 = _mm256_loadu_si256((__m256i*)(a+j+32));
            __m256i v2 = _mm256_loadu_si256((__m256i*)(a+j+64));
            __m256i v3 = _mm256_loadu_si256((__m256i*)(a+j+96));
            _mm256_storeu_si256((__m256i*)(b+j), v0);
            _mm256_storeu_si256((__m256i*)(b+j+32), v1);
            _mm256_storeu_si256((__m256i*)(b+j+64), v2);
            _mm256_storeu_si256((__m256i*)(b+j+96), v3);
        }
    }
    t1 = now();
    printf("avx2 regular copy: %.3f ms  %.1f MB/s data\n",
        (t1-t0)/iters*1000, (double)len*iters/(t1-t0)/1e6);

    // write only (nt)
    t0 = now();
    __m256i z = _mm256_setzero_si256();
    for (int i = 0; i < iters; i++) {
        for (size_t j = 0; j < len; j += 128) {
            _mm256_stream_si256((__m256i*)(b+j), z);
            _mm256_stream_si256((__m256i*)(b+j+32), z);
            _mm256_stream_si256((__m256i*)(b+j+64), z);
            _mm256_stream_si256((__m256i*)(b+j+96), z);
        }
        _mm_sfence();
    }
    t1 = now();
    printf("avx2 stream write-only: %.3f ms  %.1f MB/s\n",
        (t1-t0)/iters*1000, (double)len*iters/(t1-t0)/1e6);

    // read only
    volatile uint64_t sink = 0;
    t0 = now();
    for (int i = 0; i < iters; i++) {
        __m256i acc = _mm256_setzero_si256();
        for (size_t j = 0; j < len; j += 128) {
            acc = _mm256_xor_si256(acc, _mm256_loadu_si256((__m256i*)(a+j)));
            acc = _mm256_xor_si256(acc, _mm256_loadu_si256((__m256i*)(a+j+32)));
            acc = _mm256_xor_si256(acc, _mm256_loadu_si256((__m256i*)(a+j+64)));
            acc = _mm256_xor_si256(acc, _mm256_loadu_si256((__m256i*)(a+j+96)));
        }
        sink += _mm256_extract_epi64(acc, 0);
    }
    t1 = now();
    printf("avx2 read-only: %.3f ms  %.1f MB/s  sink=%llu\n",
        (t1-t0)/iters*1000, (double)len*iters/(t1-t0)/1e6, (unsigned long long)sink);

    printf("b0=%u\n", b[0]);
    return 0;
}
