{"command":"cat > ./bench_chacha_avx2.c << 'EOF'
#include <immintrin.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static inline __m256i rotl32(__m256i x, int n) {
    return _mm256_or_si256(_mm256_slli_epi32(x, n), _mm256_srli_epi32(x, 32 - n));
}

static inline void quarter(__m256i *a, __m256i *b, __m256i *c, __m256i *d) {
    *a = _mm256_add_epi32(*a, *b); *d = rotl32(_mm256_xor_si256(*d, *a), 16);
    *c = _mm256_add_epi32(*c, *d); *b = rotl32(_mm256_xor_si256(*b, *c), 12);
    *a = _mm256_add_epi32(*a, *b); *d = rotl32(_mm256_xor_si256(*d, *a), 8);
    *c = _mm256_add_epi32(*c, *d); *b = rotl32(_mm256_xor_si256(*b, *c), 7);
}

/* 4-lane ChaCha20 keystream into out (256 bytes). counter is block index of lane 0. */
static void chacha_blocks4(const uint32_t key[8], const uint32_t nonce[3], uint32_t counter, uint8_t out[256]) {
    const __m256i c0 = _mm256_set1_epi32(0x61707865);
    const __m256i c1 = _mm256_set1_epi32(0x3320646e);
    const __m256i c2 = _mm256_set1_epi32(0x79622d32);
    const __m256i c3 = _mm256_set1_epi32(0x6b206574);
    __m256i k0 = _mm256_set1_epi32(key[0]);
    __m256i k1 = _mm256_set1_epi32(key[1]);
    __m256i k2 = _mm256_set1_epi32(key[2]);
    __m256i k3 = _mm256_set1_epi32(key[3]);
    __m256i k4 = _mm256_set1_epi32(key[4]);
    __m256i k5 = _mm256_set1_epi32(key[5]);
    __m256i k6 = _mm256_set1_epi32(key[6]);
    __m256i k7 = _mm256_set1_epi32(key[7]);
    __m256i ctr = _mm256_set_epi32(counter+3, counter+2, counter+1, counter, counter+3, counter+2, counter+1, counter);
