    __m256i x14 = _mm256_set1_epi32(nonce[1]);
    __m256i x15 = _mm256_set1_epi32(nonce[2]);

    __m256i s0=x0,s1=x1,s2=x2,s3=x3,s4=x4,s5=x5,s6=x6,s7=x7;
    __m256i s8=x8,s9=x9,s10=x10,s11=x11,s12=x12,s13=x13,s14=x14,s15=x15;

    for (int i = 0; i < 10; i++) {
        quarter(&x0,&x4,&x8,&x12);
        quarter(&x1,&x5,&x9,&x13);
        quarter(&x2,&x6,&x10,&x14);
        quarter(&x3,&x7,&x11,&x15);
        quarter(&x0,&x5,&x10,&x15);
        quarter(&x1,&x6,&x11,&x12);
        quarter(&x2,&x7,&x8,&x13);
        quarter(&x3,&x4,&x9,&x14);
