static pthread_cond_t cv_start = PTHREAD_COND_INITIALIZER;
static pthread_cond_t cv_done = PTHREAD_COND_INITIALIZER;
static int nthreads, ready, phase, stopflag;

static void *pool_worker(void *arg){
    int id = (int)(intptr_t)arg;
    int myphase = 0;
    for(;;){
        pthread_mutex_lock(&mtx);
        while(phase==myphase && !stopflag) pthread_cond_wait(&cv_start, &mtx);
        if(stopflag){ pthread_mutex_unlock(&mtx); return NULL; }
        myphase = phase;
        pthread_mutex_unlock(&mtx);
        work(&jobs[id]);
        pthread_mutex_lock(&mtx);
        ready++;
        if(ready==nthreads) pthread_cond_signal(&cv_done);
        pthread_mutex_unlock(&mtx);
    }
}

