    printf("create %d: wall %.2f ms agg %.1f MB/s sink %llu\n", n,(t1-t0)*1000,total/(t1-t0)/1e6,(unsigned long long)jobs[0].sink);
}

int main(){
    printf("== pure compute, fresh threads ==\n");
    for(int n=1;n<=8;n++) run(n);
