/* ---------------- thread pool ---------------- */
#define MAX_THREADS 8
typedef struct {
    const __m256i *ks;
    const uint8_t *in;
    uint8_t *out;
    size_t len;
    uint32_t counter0;
} job_t;

static job_t jobs[MAX_THREADS];
static pthread_t threads[MAX_THREADS];
static pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_go = PTHREAD_COND_INITIALIZER;
static pthread_cond_t cv_done = PTHREAD_COND_INITIALIZER;
static int nthreads = 0, phase = 0, arrived = 0, pool_stop = 0, pool_ready = 0;

static void *worker(void *arg){
    int id = (int)(intptr_t)arg, seen = 0;
    for(;;){
        pthread_mutex_lock(&mtx);
        while(phase==seen && !pool_stop) pthread_cond_wait(&cv_go, &mtx);
        if(pool_stop){ pthread_mutex_unlock(&mtx); return NULL; }
        seen = phase;
        pthread_mutex_unlock(&mtx);
        job_t *j = &jobs[id];
        uint32_t ctr = j->counter0;
        const uint8_t *in = j->in; uint8_t *out = j->out;
        size_t len = j->len;
        size_t off = 0;
        for(; off + 512 <= len; off += 512){ chacha8_xor(j->ks, ctr, in+off, out+off); ctr += 8; }
        if(off < len){
            uint8_t tmp_in[512]={0}, tmp_out[512];
            memcpy(tmp_in, in+off, len-off);
            chacha8_xor(j->ks, ctr, tmp_in, tmp_out);
            memcpy(out+off, tmp_out, len-off);
        }
        _mm_sfence();
        pthread_mutex_lock(&mtx);
        arrived++;
        if(arrived==nthreads) pthread_cond_signal(&cv_done);
        pthread_mutex_unlock(&mtx);
    }
}

static void pool_init(int n){
    if(pool_ready) return;
    nthreads = n;
    for(int i=0;i<n;i++) pthread_create(&threads[i], NULL, worker, (void*)(intptr_t)i);
    pool_ready = 1;
}

static void pool_run(void){
    pthread_mutex_lock(&mtx);
    phase++; arrived = 0;
    pthread_cond_broadcast(&cv_go);
    while(arrived < nthreads) pthread_cond_wait(&cv_done, &mtx);
    pthread_mutex_unlock(&mtx);
}

/* ciphertext buffer: we write directly into caller memory */
int chacha_seal(const uint8_t key[32], const uint8_t nonce[12],
                const uint8_t *aad, size_t aad_len,
                const uint8_t *pt, size_t pt_len,
                uint8_t *ct, uint8_t tag[16]){
    pool_init(MAX_THREADS);
    uint32_t kw[8], nw[3];
    memcpy(kw, key, 32); memcpy(nw, nonce, 12);
    uint8_t otk[64];
    chacha_block(kw, nw, 0, otk);

    __m256i ks[15];
    ks[0]=_mm256_set1_epi32(0x61707865); ks[1]=_mm256_set1_epi32(0x3320646e);
    ks[2]=_mm256_set1_epi32(0x79622d32); ks[3]=_mm256_set1_epi32(0x6b206574);
    for(int i=0;i<8;i++) ks[4+i]=_mm256_set1_epi32(kw[i]);
    ks[12]=_mm256_set1_epi32(nw[0]); ks[13]=_mm256_set1_epi32(nw[1]); ks[14]=_mm256_set1_epi32(nw[2]);

    int n = nthreads;
    size_t chunk = pt_len / n;
    chunk &= ~(size_t)511;
    if(chunk == 0){
        /* small: do it here */
        uint8_t tmp_in[512]={0}, tmp_out[512];
        memcpy(tmp_in, pt, pt_len);
        chacha8_xor(ks, 1, tmp_in, tmp_out);
        memcpy(ct, tmp_out, pt_len);
    } else {
        size_t assigned = chunk * (n-1);
        for(int i=0;i<n;i++){
            size_t off = (size_t)i * chunk;
            size_t len = (i==n-1) ? (pt_len - assigned) : chunk;
            if(i==n-1) off = assigned;
            jobs[i].ks = ks; jobs[i].in = pt+off; jobs[i].out = ct+off;
            jobs[i].len = len; jobs[i].counter0 = 1 + (uint32_t)(off/64);
        }
        pool_run();
    }
    poly_aead(otk, aad ? aad : (const uint8_t*)"", aad_len, ct, pt_len, tag);
    return 0;
}

