/* ---------------- parallel dispatch (fresh threads per call) ---------------- */
#define MAX_THREADS 8
typedef struct {
    const __m256i *ks;
    const uint8_t *in;
    uint8_t *out;
    size_t len;
    uint32_t counter0;
} job_t;

static void *worker(void *arg){
    job_t *j = (job_t*)arg;
    uint32_t ctr = j->counter0;
    size_t len = j->len;
    for(size_t off=0; off<len; off+=512){ chacha8_xor(j->ks, ctr, j->in+off, j->out+off); ctr += 8; }
    _mm_sfence();
    return NULL;
}

/* ciphertext buffer: we write directly into caller memory */
int chacha_seal(const uint8_t key[32], const uint8_t nonce[12],
                const uint8_t *aad, size_t aad_len,
                const uint8_t *pt, size_t pt_len,
                uint8_t *ct, uint8_t tag[16]){
    uint32_t kw[8], nw[3];
    memcpy(kw, key, 32); memcpy(nw, nonce, 12);
    uint8_t otk[64];
    chacha_block(kw, nw, 0, otk);

    __m256i ks[15];
    ks[0]=_mm256_set1_epi32(0x61707865); ks[1]=_mm256_set1_epi32(0x3320646e);
    ks[2]=_mm256_set1_epi32(0x79622d32); ks[3]=_mm256_set1_epi32(0x6b206574);
    for(int i=0;i<8;i++) ks[4+i]=_mm256_set1_epi32(kw[i]);
    ks[12]=_mm256_set1_epi32(nw[0]); ks[13]=_mm256_set1_epi32(nw[1]); ks[14]=_mm256_set1_epi32(nw[2]);

    int n = MAX_THREADS;
    size_t chunk = pt_len / n;
    chunk &= ~(size_t)511;
    if(chunk == 0){
        /* small: do it here */
        uint8_t tmp_in[512]={0}, tmp_out[512];
        memcpy(tmp_in, pt, pt_len);
        chacha8_xor(ks, 1, tmp_in, tmp_out);
        memcpy(ct, tmp_out, pt_len);
    } else {
        size_t main_len = chunk * n;
        job_t jobs[MAX_THREADS];
        pthread_t threads[MAX_THREADS];
        for(int i=0;i<n;i++){
            size_t off = (size_t)i * chunk;
            jobs[i].ks = ks; jobs[i].in = pt+off; jobs[i].out = ct+off;
            jobs[i].len = chunk; jobs[i].counter0 = 1 + (uint32_t)(off/64);
            pthread_create(&threads[i], NULL, worker, &jobs[i]);
        }
        for(int i=0;i<n;i++) pthread_join(threads[i], NULL);
        if(main_len < pt_len){
            uint8_t tmp_in[512]={0}, tmp_out[512];
            size_t rem = pt_len - main_len;
            memcpy(tmp_in, pt+main_len, rem);
            chacha8_xor(ks, 1 + (uint32_t)(main_len/64), tmp_in, tmp_out);
            memcpy(ct+main_len, tmp_out, rem);
        }
    }
    poly_aead(otk, aad ? aad : (const uint8_t*)"", aad_len, ct, pt_len, tag);
    return 0;
}

