    const __m256i *ks;
    const uint8_t *in;
    uint8_t *out;
    size_t len;
    uint32_t counter0;
} job_t;

static void *worker(void *arg){
    job_t *j = (job_t*)arg;
    xor_range(j->ks, j->counter0, j->in, j->out, j->len);
    return NULL;
}

