/* ---------------- parallel dispatch (fresh threads per call) ---------------- */
#define MAX_THREADS 8

/* xor len bytes of in into out. Handles a partial trailing block. counter is the block index of in[0]. */
static void xor_range(const __m256i *ks, uint32_t counter, const uint8_t *in, uint8_t *out, size_t len){
    size_t off = 0;
    for(; off + 512 <= len; off += 512){ chacha8_xor(ks, counter, in+off, out+off); counter += 8; }
    if(off < len){
        uint8_t tmp_in[512] __attribute__((aligned(64)));
        uint8_t tmp_out[512] __attribute__((aligned(64)));
        memset(tmp_in, 0, 512);
        memcpy(tmp_in, in+off, len-off);
        chacha8_xor(ks, counter, tmp_in, tmp_out);
        memcpy(out+off, tmp_out, len-off);
    }
    _mm_sfence();
}

typedef struct {
    const __m256i *ks;
    const uint8_t *in;
    uint8_t *out;
    size_t len;
    uint32_t counter0;
} job_t;

static void *worker(void *arg){
    job_t *j = (job_t*)arg;
    xor_range(j->ks, j->counter0, j->in, j->out, j->len);
    return NULL;
}

