/* Parallel AVX2 ChaCha20-Poly1305 (RFC 8439) seal.
 *
 * The plaintext is split across threads. Each thread encrypts its slice with an
 * 8-block-wide AVX2 ChaCha20 and folds the resulting ciphertext into a Poly1305
 * accumulator. The main thread combines the partial accumulators (Poly1305 is a
 * polynomial evaluation, so partial results recombine with powers of r) and
 * finishes the tag. This overlaps the authentication with the encryption.
 */
#include <immintrin.h>
#include <pthread.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define ROTL(x,n) _mm256_or_si256(_mm256_slli_epi32(x,n),_mm256_srli_epi32(x,32-(n)))
#define QR(a,b,c,d) do{ a=_mm256_add_epi32(a,b); d=ROTL(_mm256_xor_si256(d,a),16); c=_mm256_add_epi32(c,d); b=ROTL(_mm256_xor_si256(b,c),12); a=_mm256_add_epi32(a,b); d=ROTL(_mm256_xor_si256(d,a),8); c=_mm256_add_epi32(c,d); b=ROTL(_mm256_xor_si256(b,c),7);}while(0)

static inline void transpose8(__m256i *r){
    __m256i t0=_mm256_unpacklo_epi32(r[0],r[1]); __m256i t1=_mm256_unpackhi_epi32(r[0],r[1]);
    __m256i t2=_mm256_unpacklo_epi32(r[2],r[3]); __m256i t3=_mm256_unpackhi_epi32(r[2],r[3]);
    __m256i t4=_mm256_unpacklo_epi32(r[4],r[5]); __m256i t5=_mm256_unpackhi_epi32(r[4],r[5]);
    __m256i t6=_mm256_unpacklo_epi32(r[6],r[7]); __m256i t7=_mm256_unpackhi_epi32(r[6],r[7]);
    __m256i u0=_mm256_unpacklo_epi64(t0,t2); __m256i u1=_mm256_unpackhi_epi64(t0,t2);
    __m256i u2=_mm256_unpacklo_epi64(t1,t3); __m256i u3=_mm256_unpackhi_epi64(t1,t3);
    __m256i u4=_mm256_unpacklo_epi64(t4,t6); __m256i u5=_mm256_unpackhi_epi64(t4,t6);
    __m256i u6=_mm256_unpacklo_epi64(t5,t7); __m256i u7=_mm256_unpackhi_epi64(t5,t7);
    r[0]=_mm256_permute2x128_si256(u0,u4,0x20); r[1]=_mm256_permute2x128_si256(u1,u5,0x20);
    r[2]=_mm256_permute2x128_si256(u2,u6,0x20); r[3]=_mm256_permute2x128_si256(u3,u7,0x20);
    r[4]=_mm256_permute2x128_si256(u0,u4,0x31); r[5]=_mm256_permute2x128_si256(u1,u5,0x31);
    r[6]=_mm256_permute2x128_si256(u2,u6,0x31); r[7]=_mm256_permute2x128_si256(u3,u7,0x31);
}

/* encrypt 512 bytes. ks must be 32-byte aligned. stores are unaligned-safe. */
static void chacha8_xor(const __m256i *ks, uint32_t counter, const uint8_t *in, uint8_t *out){
    __m256i c0=ks[0],c1=ks[1],c2=ks[2],c3=ks[3];
    __m256i k0=ks[4],k1=ks[5],k2=ks[6],k3=ks[7],k4=ks[8],k5=ks[9],k6=ks[10],k7=ks[11];
    __m256i n0=ks[12],n1=ks[13],n2=ks[14];
    __m256i a0=c0,a1=c1,a2=c2,a3=c3,a4=k0,a5=k1,a6=k2,a7=k3,a8=k4,a9=k5,a10=k6,a11=k7;
    __m256i a12=_mm256_add_epi32(_mm256_set1_epi32(counter), _mm256_setr_epi32(0,1,2,3,4,5,6,7));
    __m256i a13=n0,a14=n1,a15=n2, sa12=a12;
    for(int r=0;r<10;r++){
        QR(a0,a4,a8,a12); QR(a1,a5,a9,a13); QR(a2,a6,a10,a14); QR(a3,a7,a11,a15);
        QR(a0,a5,a10,a15); QR(a1,a6,a11,a12); QR(a2,a7,a8,a13); QR(a3,a4,a9,a14);
    }
