    a4=_mm256_add_epi32(a4,k0);a5=_mm256_add_epi32(a5,k1);a6=_mm256_add_epi32(a6,k2);a7=_mm256_add_epi32(a7,k3);
    a8=_mm256_add_epi32(a8,k4);a9=_mm256_add_epi32(a9,k5);a10=_mm256_add_epi32(a10,k6);a11=_mm256_add_epi32(a11,k7);
    a12=_mm256_add_epi32(a12,sa12);a13=_mm256_add_epi32(a13,n0);a14=_mm256_add_epi32(a14,n1);a15=_mm256_add_epi32(a15,n2);
    __m256i lo[8]={a0,a1,a2,a3,a4,a5,a6,a7};
    __m256i hi[8]={a8,a9,a10,a11,a12,a13,a14,a15};
    transpose8(lo); transpose8(hi);
    int aligned = (((uintptr_t)out & 31) == 0);
    for(int i=0;i<8;i++){
        __m256i p0=_mm256_loadu_si256((const __m256i*)(in+i*64));
        __m256i p1=_mm256_loadu_si256((const __m256i*)(in+i*64+32));
        __m256i o0=_mm256_xor_si256(lo[i], p0);
        __m256i o1=_mm256_xor_si256(hi[i], p1);
        if(aligned){
            _mm256_stream_si256((__m256i*)(out+i*64), o0);
            _mm256_stream_si256((__m256i*)(out+i*64+32), o1);
        } else {
            _mm256_storeu_si256((__m256i*)(out+i*64), o0);
            _mm256_storeu_si256((__m256i*)(out+i*64+32), o1);
        }
