static void chacha_block(const uint32_t key[8], const uint32_t nonce[3], uint32_t counter, uint8_t out[64]){
    uint32_t x[16], s[16];
    s[0]=0x61707865; s[1]=0x3320646e; s[2]=0x79622d32; s[3]=0x6b206574;
    for(int i=0;i<8;i++) s[4+i]=key[i];
    s[12]=counter; s[13]=nonce[0]; s[14]=nonce[1]; s[15]=nonce[2];
    memcpy(x,s,64);
    #define QQ(a,b,c,d) do{ uint32_t ta=x[a]+x[b]; uint32_t td=x[d]^ta; td=(td<<16)|(td>>16); uint32_t tc=x[c]+td; uint32_t tb=x[b]^tc; tb=(tb<<12)|(tb>>20); ta+=tb; td^=ta; td=(td<<8)|(td>>24); tc+=td; tb^=tc; tb=(tb<<7)|(tb>>25); x[a]=ta; x[b]=tb; x[c]=tc; x[d]=td; }while(0)
    for(int i=0;i<10;i++){
        QQ(0,4,8,12); QQ(1,5,9,13); QQ(2,6,10,14); QQ(3,7,11,15);
        QQ(0,5,10,15); QQ(1,6,11,12); QQ(2,7,8,13); QQ(3,4,9,14);
    }
    for(int i=0;i<16;i++){ uint32_t v=x[i]+s[i]; memcpy(out+4*i,&v,4); }
}

/* ---------------- poly1305 (26-bit limbs, modulo 2^130-5) ---------------- */
typedef struct { uint32_t r[5], h[5], pad[4]; } poly;

static void poly_init(poly *p, const uint8_t key[32]){
    uint32_t t0,t1,t2,t3;
    memcpy(&t0,key,4); memcpy(&t1,key+4,4); memcpy(&t2,key+8,4); memcpy(&t3,key+12,4);
    p->r[0]=t0 & 0x3ffffff; p->r[1]=((t0>>26)|(t1<<6)) & 0x3ffff03;
    p->r[2]=((t1>>20)|(t2<<12)) & 0x3ffc0ff; p->r[3]=((t2>>14)|(t3<<18)) & 0x3f03fff;
    p->r[4]=(t3>>8) & 0x00fffff;
    memcpy(&p->pad[0],key+16,4); memcpy(&p->pad[1],key+20,4);
    memcpy(&p->pad[2],key+24,4); memcpy(&p->pad[3],key+28,4);
    p->h[0]=p->h[1]=p->h[2]=p->h[3]=p->h[4]=0;
