/* one modular multiplication h = h * q  (both 5x26-bit), fully carried */
static void mul_mod(uint32_t h[5], const uint32_t q[5]){
    uint32_t q0=q[0],q1=q[1],q2=q[2],q3=q[3],q4=q[4];
    uint32_t s1=q1*5, s2=q2*5, s3=q3*5, s4=q4*5;
    uint32_t h0=h[0],h1=h[1],h2=h[2],h3=h[3],h4=h[4];
    uint64_t d0=(uint64_t)h0*q0+(uint64_t)h1*s4+(uint64_t)h2*s3+(uint64_t)h3*s2+(uint64_t)h4*s1;
    uint64_t d1=(uint64_t)h0*q1+(uint64_t)h1*q0+(uint64_t)h2*s4+(uint64_t)h3*s3+(uint64_t)h4*s2;
    uint64_t d2=(uint64_t)h0*q2+(uint64_t)h1*q1+(uint64_t)h2*q0+(uint64_t)h3*s4+(uint64_t)h4*s3;
    uint64_t d3=(uint64_t)h0*q3+(uint64_t)h1*q2+(uint64_t)h2*q1+(uint64_t)h3*q0+(uint64_t)h4*s4;
    uint64_t d4=(uint64_t)h0*q4+(uint64_t)h1*q3+(uint64_t)h2*q2+(uint64_t)h3*q1+(uint64_t)h4*q0;
    uint64_t c;
    c=d0>>26; h0=(uint32_t)d0 & 0x3ffffff; d1+=c;
    c=d1>>26; h1=(uint32_t)d1 & 0x3ffffff; d2+=c;
    c=d2>>26; h2=(uint32_t)d2 & 0x3ffffff; d3+=c;
    c=d3>>26; h3=(uint32_t)d3 & 0x3ffffff; d4+=c;
    c=d4>>26; h4=(uint32_t)d4 & 0x3ffffff; h0+=(uint32_t)c*5;
    c=h0>>26; h0&=0x3ffffff; h1+=(uint32_t)c;
    h[0]=h0; h[1]=h1; h[2]=h2; h[3]=h3; h[4]=h4;
}

static void poly_blocks(poly *p, const uint8_t *m, size_t bytes){
    uint32_t r0=p->r[0],r1=p->r[1],r2=p->r[2],r3=p->r[3],r4=p->r[4];
    uint32_t s1=r1*5, s2=r2*5, s3=r3*5, s4=r4*5;
    uint32_t h0=p->h[0],h1=p->h[1],h2=p->h[2],h3=p->h[3],h4=p->h[4];
    while(bytes>=16){
        uint32_t t0,t1,t2,t3; memcpy(&t0,m,4); memcpy(&t1,m+4,4); memcpy(&t2,m+8,4); memcpy(&t3,m+12,4);
        h0 += t0 & 0x3ffffff;
        h1 += ((t0>>26)|(t1<<6)) & 0x3ffffff;
        h2 += ((t1>>20)|(t2<<12)) & 0x3ffffff;
        h3 += ((t2>>14)|(t3<<18)) & 0x3ffffff;
        h4 += (t3>>8) | (1u<<24);
        uint64_t d0=(uint64_t)h0*r0+(uint64_t)h1*s4+(uint64_t)h2*s3+(uint64_t)h3*s2+(uint64_t)h4*s1;
        uint64_t d1=(uint64_t)h0*r1+(uint64_t)h1*r0+(uint64_t)h2*s4+(uint64_t)h3*s3+(uint64_t)h4*s2;
        uint64_t d2=(uint64_t)h0*r2+(uint64_t)h1*r1+(uint64_t)h2*r0+(uint64_t)h3*s4+(uint64_t)h4*s3;
        uint64_t d3=(uint64_t)h0*r3+(uint64_t)h1*r2+(uint64_t)h2*r1+(uint64_t)h3*r0+(uint64_t)h4*s4;
        uint64_t d4=(uint64_t)h0*r4+(uint64_t)h1*r3+(uint64_t)h2*r2+(uint64_t)h3*r1+(uint64_t)h4*r0;
        uint64_t c;
        c=d0>>26; h0=(uint32_t)d0 & 0x3ffffff; d1+=c;
        c=d1>>26; h1=(uint32_t)d1 & 0x3ffffff; d2+=c;
        c=d2>>26; h2=(uint32_t)d2 & 0x3ffffff; d3+=c;
        c=d3>>26; h3=(uint32_t)d3 & 0x3ffffff; d4+=c;
        c=d4>>26; h4=(uint32_t)d4 & 0x3ffffff; h0+=(uint32_t)c*5;
        c=h0>>26; h0&=0x3ffffff; h1+=(uint32_t)c;
        m+=16; bytes-=16;
    }
    p->h[0]=h0; p->h[1]=h1; p->h[2]=h2; p->h[3]=h3; p->h[4]=h4;
}

/* absorb a region, zero-padding the final partial block (RFC 8439 pad16) */
static void poly_absorb(poly *p, const uint8_t *m, size_t len){
    poly_blocks(p, m, len & ~(size_t)15);
    if(len & 15){
        uint8_t block[16]={0};
        memcpy(block, m+(len & ~(size_t)15), len & 15);
        poly_blocks(p, block, 16);
    }
}

static void poly_finish(poly *p, uint8_t tag[16]){
    uint32_t h0=p->h[0],h1=p->h[1],h2=p->h[2],h3=p->h[3],h4=p->h[4];
    uint32_t c;
    c=h1>>26; h1&=0x3ffffff; h2+=c;
    c=h2>>26; h2&=0x3ffffff; h3+=c;
    c=h3>>26; h3&=0x3ffffff; h4+=c;
    c=h4>>26; h4&=0x3ffffff; h0+=c*5;
    c=h0>>26; h0&=0x3ffffff; h1+=c;
    uint32_t g0=h0+5, g1=h1, g2=h2, g3=h3, g4=h4;
    c=g0>>26; g0&=0x3ffffff; g1+=c;
    c=g1>>26; g1&=0x3ffffff; g2+=c;
    c=g2>>26; g2&=0x3ffffff; g3+=c;
    c=g3>>26; g3&=0x3ffffff; g4+=c;
    uint32_t mask=(g4>>26)-1u; g4&=0x3ffffff;
    h0=(h0 & mask)|(g0 & ~mask); h1=(h1 & mask)|(g1 & ~mask);
    h2=(h2 & mask)|(g2 & ~mask); h3=(h3 & mask)|(g3 & ~mask);
    h4=(h4 & mask)|(g4 & ~mask);
    uint32_t w0=h0|((h1 & 0x3f)<<26);
    uint32_t w1=(h1>>6)|((h2 & 0xfff)<<20);
    uint32_t w2=(h2>>12)|((h3 & 0x3ffff)<<14);
    uint32_t w3=(h3>>18)|(h4<<8);
    uint64_t acc; uint32_t cy;
    acc=(uint64_t)w0+p->pad[0]; uint32_t o0=(uint32_t)acc; cy=(uint32_t)(acc>>32);
    acc=(uint64_t)w1+p->pad[1]+cy; uint32_t o1=(uint32_t)acc; cy=(uint32_t)(acc>>32);
    acc=(uint64_t)w2+p->pad[2]+cy; uint32_t o2=(uint32_t)acc; cy=(uint32_t)(acc>>32);
    acc=(uint64_t)w3+p->pad[3]+cy; uint32_t o3=(uint32_t)acc;
    memcpy(tag,&o0,4); memcpy(tag+4,&o1,4); memcpy(tag+8,&o2,4); memcpy(tag+12,&o3,4);
}

/* r^k via square-and-multiply (k = number of 16-byte blocks) */
static void r_power(const uint32_t r[5], uint64_t k, uint32_t out[5]){
    uint32_t base[5]={r[0],r[1],r[2],r[3],r[4]};
    uint32_t res[5]={1,0,0,0,0};
    while(k){
        if(k & 1) mul_mod(res, base);
        k >>= 1;
        if(k){ uint32_t sq[5]={base[0],base[1],base[2],base[3],base[4]}; mul_mod(base, sq); }
    }
    memcpy(out, res, sizeof(res));
}

/* ---------------- encryption of a byte range ---------------- */
static void xor_range(const __m256i *ks, uint32_t counter, const uint8_t *in, uint8_t *out, size_t len){
    size_t off=0;
    for(; off+512<=len; off+=512){ chacha8_xor(ks, counter, in+off, out+off); counter+=8; }
    if(off<len){
        uint8_t *tmp_in=(uint8_t*)aligned_alloc(64,512);
        uint8_t *tmp_out=(uint8_t*)aligned_alloc(64,512);
        memset(tmp_in,0,512);
        memcpy(tmp_in, in+off, len-off);
        chacha8_xor(ks, counter, tmp_in, tmp_out);
        memcpy(out+off, tmp_out, len-off);
        free(tmp_in); free(tmp_out);
    }
    _mm_sfence();
}

/* ---------------- parallel driver ---------------- */
#define MAX_THREADS 8
typedef struct {
    const __m256i *ks;
    const uint8_t *in;
    uint8_t *out;
    size_t len;
    uint32_t counter0;
    const poly *base;   /* r and pad; h ignored */
    poly acc;           /* output accumulator for this slice */
} job_t;

static void *worker(void *arg){
    job_t *j=(job_t*)arg;
    xor_range(j->ks, j->counter0, j->in, j->out, j->len);
    j->acc=*j->base;
    j->acc.h[0]=j->acc.h[1]=j->acc.h[2]=j->acc.h[3]=j->acc.h[4]=0;
    poly_blocks(&j->acc, j->out, j->len & ~(size_t)15);
    return NULL;
}

int chacha_seal(const uint8_t key[32], const uint8_t nonce[12],
                const uint8_t *aad, size_t aad_len,
                const uint8_t *pt, size_t pt_len,
                uint8_t *ct, uint8_t tag[16]){
    uint32_t kw[8], nw[3];
    memcpy(kw, key, 32); memcpy(nw, nonce, 12);

    uint8_t otk[64];
    chacha_block(kw, nw, 0, otk);

    __m256i ks[15] __attribute__((aligned(64)));
    ks[0]=_mm256_set1_epi32(0x61707865); ks[1]=_mm256_set1_epi32(0x3320646e);
    ks[2]=_mm256_set1_epi32(0x79622d32); ks[3]=_mm256_set1_epi32(0x6b206574);
    for(int i=0;i<8;i++) ks[4+i]=_mm256_set1_epi32(kw[i]);
    ks[12]=_mm256_set1_epi32(nw[0]); ks[13]=_mm256_set1_epi32(nw[1]); ks[14]=_mm256_set1_epi32(nw[2]);

    poly base; poly_init(&base, otk);

    int n = MAX_THREADS;
    size_t chunk = pt_len / n;
    if(chunk < 4096){
        /* small: single threaded */
        xor_range(ks, 1, pt, ct, pt_len);
        poly acc=base; acc.h[0]=acc.h[1]=acc.h[2]=acc.h[3]=acc.h[4]=0;
        poly_absorb(&acc, aad?aad:(const uint8_t*)"", aad_len);
        poly_absorb(&acc, ct, pt_len);
        uint8_t lens[16]; uint64_t al=aad_len, cl=pt_len;
        memcpy(lens,&al,8); memcpy(lens+8,&cl,8);
        poly_blocks(&acc, lens, 16);
        poly_finish(&acc, tag);
        return 0;
    }
    chunk &= ~(size_t)511;

    job_t jobs[MAX_THREADS];
    pthread_t threads[MAX_THREADS];
    size_t off=0;
    int spawned=0;
    for(int i=0;i<n-1;i++){
        jobs[i].ks=ks; jobs[i].in=pt+off; jobs[i].out=ct+off;
        jobs[i].len=chunk; jobs[i].counter0=1+(uint32_t)(off/64);
        jobs[i].base=&base;
        pthread_create(&threads[i], NULL, worker, &jobs[i]);
        spawned++;
        off+=chunk;
    }
    /* main thread: tail region (last chunk + remainder) */
    size_t tail_off=off;
    xor_range(ks, 1+(uint32_t)(tail_off/64), pt+tail_off, ct+tail_off, pt_len-tail_off);

    for(int i=0;i<spawned;i++) pthread_join(threads[i], NULL);

    /* combine partial ciphertext accumulators: h = sum_i h_i * r^(blocks after slice i) */
    uint64_t total_blocks = pt_len / 16;
    poly acc=base; acc.h[0]=acc.h[1]=acc.h[2]=acc.h[3]=acc.h[4]=0;
    poly_absorb(&acc, aad?aad:(const uint8_t*)"", aad_len);

    for(int i=0;i<spawned;i++){
        uint64_t slice_end_block = (off) / 16;            /* all spawned slices end at 'off' cumulatively? no */
        (void)slice_end_block;
    }
    /* recompute per-slice block ranges: slice i covers bytes [i*chunk, (i+1)*chunk) */
    size_t cursor=0;
    for(int i=0;i<spawned;i++){
        uint64_t after = total_blocks - (cursor + jobs[i].len)/16;
        uint32_t pw[5]; r_power(base.r, after, pw);
        uint32_t hh[5]={jobs[i].acc.h[0],jobs[i].acc.h[1],jobs[i].acc.h[2],jobs[i].acc.h[3],jobs[i].acc.h[4]};
        mul_mod(hh, pw);
        acc.h[0]+=hh[0]; acc.h[1]+=hh[1]; acc.h[2]+=hh[2]; acc.h[3]+=hh[3]; acc.h[4]+=hh[4];
        cursor += jobs[i].len;
    }
    /* tail region processed directly into acc */
    poly_absorb(&acc, ct+tail_off, pt_len-tail_off);

    /* carry the summed accumulator back into range before finishing */
    {
        uint32_t h0=acc.h[0],h1=acc.h[1],h2=acc.h[2],h3=acc.h[3],h4=acc.h[4];
        uint64_t c;
        c=h0>>26; h0&=0x3ffffff; h1+=(uint32_t)c;
        c=h1>>26; h1&=0x3ffffff; h2+=(uint32_t)c;
        c=h2>>26; h2&=0x3ffffff; h3+=(uint32_t)c;
        c=h3>>26; h3&=0x3ffffff; h4+=(uint32_t)c;
        c=h4>>26; h4&=0x3ffffff; h0+=(uint32_t)c*5;
        c=h0>>26; h0&=0x3ffffff; h1+=(uint32_t)c;
        acc.h[0]=h0; acc.h[1]=h1; acc.h[2]=h2; acc.h[3]=h3; acc.h[4]=h4;
    }

    uint8_t lens[16]; uint64_t al=aad_len, cl=pt_len;
    memcpy(lens,&al,8); memcpy(lens+8,&cl,8);
    poly_blocks(&acc, lens, 16);
    poly_finish(&acc, tag);
    return 0;
}
