import os, struct, subprocess
from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305
bad=0
def check(n, aadlen):
    global bad
    key=os.urandom(32); nonce=os.urandom(12); aad=os.urandom(aadlen); pt=os.urandom(n)
    data = key+nonce+struct.pack('<I',len(aad))+aad+struct.pack('<I',n)+pt
