    ref = ChaCha20Poly1305(key).encrypt(nonce, pt, aad if aad else None)
    if ct!=ref[:-16] or tag!=ref[-16:]:
        bad+=1; print('BAD', n, aadlen, 'tag' if tag!=ref[-16:] else 'ct')
for n in [0,1,513,4096,10000,32768,50000,100000,1<<20,40<<20]:
